#!/usr/bin/env python3
"""Build browser data, recording guide and CSV from the same curriculum source."""
from pathlib import Path
import csv,html,io,json
ROOT=Path(__file__).resolve().parent
data=json.loads((ROOT/'curriculum.json').read_text())
levels=data['levels']; version=data['version']
flat=[c for g in levels for c in g['cards']]
assert len({c['id'] for c in flat})==len(flat),'Duplicate stable card ID'
assert [c['recordingId']for c in flat]==[f'{version}-{i:03d}'for i in range(1,len(flat)+1)],'Recording sequence mismatch'
stages=['words','short','medium','long']
assert [stages.index(g['stage'])for g in levels]==sorted(stages.index(g['stage'])for g in levels),'Vocabulary must precede progressively longer sentences'
word_ids={c['id']for g in levels if g['stage']=='words'for c in g['cards']}
practiced={p for g in levels for c in g['cards']for p in c.get('practices',[])}
assert word_ids<=practiced,'Every vocabulary card needs sentence practice'
assert practiced<=word_ids,'Sentence practice points to an unknown vocabulary card'
assert set(range(21))<={c.get('number')for g in levels if g['stage']=='words'for c in g['cards']}
assert set(range(10,101,10))<={c.get('number')for g in levels if g['stage']=='words'for c in g['cards']}
(ROOT/'vocabulary.js').write_text('// Generated by build-curriculum.py from curriculum.json.\nconst curriculumLevels = '+json.dumps(levels,ensure_ascii=False,indent=2)+';\n')
out=io.StringIO(); writer=csv.writer(out);writer.writerow(['Recording ID','Level','Stage','English cue','Hebrew to record','Notes'])
esc=html.escape
labels={'words':'Part 1: Words and Numbers','short':'Part 2: Short Sentences','medium':'Part 3: Medium Sentences','long':'Part 4: Longer Sentences'}
counts={s:sum(len(g['cards'])for g in levels if g['stage']==s)for s in stages}
toc='';sections='';stage=None
for i,g in enumerate(levels,1):
 cards=g['cards'];start=cards[0]['recordingId'];end=cards[-1]['recordingId'];note=g.get('note','')
 if g['stage']!=stage:
  toc+=f'<li class="part">{labels[g["stage"]]}</li>';sections+=f'<h2 class="part-heading">{labels[g["stage"]]}</h2>';stage=g['stage']
 toc+=f'<li><a href="#group-{i}">{esc(g["title"])}</a> <span>{start} – {end} · {len(cards)} cards</span></li>'
 sections+=f'<section id="group-{i}"><h3>{esc(g["title"])}</h3><p class="range">{start} – {end} · {len(cards)} cards</p>'
 if note:sections+='<p class="note">'+esc(note)+'</p>'
 sections+='<p class="batches">Suggested files: '+', '.join(f'Hebrew {version} {cards[j]["recordingId"].split("-")[1]}–{cards[min(j+19,len(cards)-1)]["recordingId"].split("-")[1]}'for j in range(0,len(cards),20))+'</p>'
 sections+='<table><thead><tr><th>Recording ID</th><th>Hebrew to record</th><th>English cue</th></tr></thead><tbody>'
 for c in cards:
  writer.writerow([c['recordingId'],g['title'],g['stage'],c['english'],c['hebrew'],note])
  sections+=f'<tr><td>{c["recordingId"]}</td><td lang="he" dir="rtl">{esc(c["hebrew"])}</td><td>{esc(c["english"])}</td></tr>'
 sections+='</tbody></table><p class="top-link"><a href="#contents">Back to contents ↑</a></p></section>'
(ROOT/'recording-list-v2.csv').write_text('\ufeff'+out.getvalue())
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hebrew recording list v2</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{font:17px/1.55 system-ui;max-width:1050px;margin:24px auto;padding:0 18px;background:#f7f4ed;color:#20303b}h1{line-height:1.2}a{color:#174b83}h2,h3{scroll-margin-top:20px}h3{font-size:1.35rem;margin-bottom:6px}table{width:100%;border-collapse:collapse;background:#fff;table-layout:fixed}th,td{border-bottom:1px solid #d9e2ec;padding:12px;vertical-align:top;text-align:left;overflow-wrap:break-word}th:first-child,td:first-child{width:100px;font-variant-numeric:tabular-nums}td[lang=he]{font-family:Arial,system-ui;font-size:24px;line-height:1.6;text-align:right}section{margin:35px 0}.intro,.note{background:#fff;padding:16px;border-radius:12px;border:1px solid #d9e2ec}.note{font-weight:600}.range,.batches{color:#52606d}.range{font-weight:700}.batches{font-size:.9rem}.part-heading{margin-top:55px;border-top:2px solid #bcccdc;padding-top:20px}#contents ul{padding-left:22px}#contents li{margin:7px 0}#contents span{display:block;color:#52606d;font-size:.9rem}#contents .part{font-weight:800;list-style:none;margin:22px 0 10px -22px}.actions{display:flex;flex-wrap:wrap;gap:12px}.actions a,.actions button{border:1px solid #bcccdc;border-radius:8px;padding:10px;background:white;font:inherit;cursor:pointer;color:#174b83}.top-link{font-size:.9rem}@media(max-width:600px){body{font-size:15px;padding:0 10px}th,td{padding:8px}th:first-child,td:first-child{width:70px;font-size:12px}td[lang=he]{font-size:20px}h1{font-size:1.8rem}}@media print{body{max-width:none;background:white;font-size:11pt}.actions,.top-link{display:none}h2,h3{break-after:avoid}tr{break-inside:avoid}td[lang=he]{font-size:15pt}.intro{border:0;padding:0}a{color:inherit;text-decoration:none}}
</style></head><body><h1>Record Hebrew for Tyler · v2</h1><p><a href="index.html">← Back to Hebrew Cards</a></p><div class="intro"><p><strong>New curriculum and numbering.</strong> This v2 list replaces the previous 286-card list. Record all items from scratch using the IDs below. The game and this list use exactly the same order.</p><p>SUMMARY</p><ol><li>Use Voice Memos in a quiet room. Record one suggested batch at a time.</li><li>Say the item's number in English, pause for about one second, then say the complete Hebrew word or sentence naturally. Leave about two seconds before the next item.</li><li>Name each file with its edition and range, such as <strong>Hebrew v2 001–008</strong>. You only need to speak the number, not “v2”.</li><li>If you make a mistake, say “again”, repeat the number, and read the item again. Send the audio files in chat for splitting and matching.</li></ol><p><strong>For sentences:</strong> record the full sentence as one natural utterance. Do not pause between every word. English is a meaning cue; record only the Hebrew. Gender labels describe the intended form, and sentence practice also shows inflected forms. Standalone numbers use feminine counting forms; counted nouns may require masculine forms.</p><p>This is a practical learning curriculum, not a developmental assessment. Existing first-eight test clips remain available until replaced. Recordings added to the public website can be heard by anyone who visits it.</p></div><p class="actions"><a href="recording-list-v2.csv" download>Download recording list (CSV)</a><button type="button" onclick="window.print()">Print recording list</button></p><nav id="contents" aria-label="Recording groups"><h2>Contents and recording ranges</h2><ul>TOC</ul></nav>SECTIONS</body></html>'''
summary=f'{len(flat)} cards across {len(levels)} groups: {counts["words"]} word and number cards first, then {counts["short"]} short, {counts["medium"]} medium, and {counts["long"]} longer sentences. Every vocabulary card is revisited in sentence practice.'
(ROOT/'recording-list.html').write_text(page.replace('SUMMARY',summary).replace('TOC',toc).replace('SECTIONS',sections))
print(summary)
